type StructSchemaGenerator struct {
	structName string
}

func (g *StructSchemaGenerator) Run(passes []parser.ParsePass, data interface{}) error {
	if len(passes) != 1 || passes[0] != parser.StructTag {
		return fmt.Errorf("only the 'structtag' pass should be used")
	}
	if data == nil {
		return fmt.Errorf("data cannot be nil")
	}

	file, err := os.Open(data.(*os.File).Path)
	if err != nil {
		return fmt.Errorf("failed to open file: %w", err)
	}
	defer file.Close()

	content, err := ioutil.ReadAll(file)
	if err != nil {
		return fmt.Errorf("failed to read file content: %w", err)
	}

	var astFile *ast.File
	if err := parser.ParseFile(token.NewFileSet(), "main.go", content, parser.ParseComments); err != nil {
		return fmt.Errorf("failed to parse file: %w", err)
	}
	astFile = astFile.(*ast.File)

	// Find the struct declaration
	for _, decl := range astFile.Decls {
		if ty, ok := decl.(*ast.TypeSpec); ok && ty.Name.Name == g.structName {
			break
		}
	}

	if !ok {
		return fmt.Errorf("struct not found in file")
	}

	// Parse the struct fields
	fields := make([]structField, 0, len(astFile.Decls))
